          ]
        },
        {
          "proposicao": "A inversão de fase pode ocorrer com a variação de temperatura, natureza ou adição de desemulsificante, porcentagem em volume da fase dispersa e fase em que o emulsificante está dissolvido.",
          "trechos": [
            "E2d98773bd11c70f1:695:1391",
            "E2d98773bd11c70f1:1391:2087"
          ],
          "condicoes": [
            "Aplica-se ao fenômeno de inversão de fase em emulsões",
            "Depende da variação das condições listadas pela fonte"
